; A chandler's: the counter across the middle with the shopkeeper behind it and the prices chalked up
; beside it, shelves and racks along the back wall, crates, sacks and barrels of stock about the floor,
; a rug for the customers, and a ship's captain haggling.

[map]
id = shop
name = The Chandler's
tileset = interior
size = 16 10
dark = yes
ambient = 0.7
fog = no
music = Exploring

[legend]
- = floor-wood
s = floor-stone
r = rug
# = wall-top
| = wall-face
_ = wall-base

